    @Test
    /** 
     * Full Create-Read-Update-Delete of a Anomaly, through a AnomalyTest.
     */
    public void testCRUD() throws Throwable {        
        try {
        	LOGGER.info( "**********************************************************" );
            LOGGER.info( "Beginning full test on AnomalyTest..." );
            
            testCreate();            
            testRead();        
            testUpdate();
            testGetAll();                
            testDelete();
            
            LOGGER.info( "Successfully ran a full test on AnomalyTest..." );
            LOGGER.info( "**********************************************************" );
            LOGGER.info( "" );
        }
        catch( Throwable e ) {
            throw e;
        }
        finally  {
        	if ( handler != null ) {
        		handler.flush();
        		LOGGER.removeHandler(handler);
        	}
        }
   }

    /** 
     * Tests creating a new Anomaly.
     *
     * @return    Anomaly
     */
    public Anomaly testCreate() throws Throwable {
        Anomaly entity = null;

        LOGGER.info( "AnomalyTest:testCreate()" );
        LOGGER.info( "-- Attempting to create a Anomaly");

        StringBuilder msg = new StringBuilder( "-- Failed to create a Anomaly" );

        try {            
            entity = AnomalyBusinessDelegate.getAnomalyInstance().createAnomaly( generateNewCommand() );
            assertNotNull( entity, msg.toString() );

            theId = entity.getAnomalyId();
            assertNotNull( theId, msg.toString() + " Contains a null primary key" );

            LOGGER.info( "-- Successfully created a Anomaly with primary key" + theId );
        }
        catch (Exception e)  {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( msg.toString() + entity );
            
            throw e;
        }
        return entity;
    }

    /** 
     * Tests reading a Anomaly.
     *
     * @return    Anomaly  
     */
    public Anomaly testRead() throws Throwable {
        LOGGER.info( "AnomalyTest:testRead()" );
        LOGGER.info( "-- Reading a previously created Anomaly" );

        Anomaly entity = null;
        StringBuilder msg = new StringBuilder( "-- Failed to read Anomaly with primary key" );
        msg.append( theId );

        try {
            entity = AnomalyBusinessDelegate.getAnomalyInstance().getAnomaly( new AnomalyFetchOneSummary(theId) );
            
            assertNotNull( entity,msg.toString() );

            // for use later
            theId = entity.getAnomalyId();
            
            LOGGER.info( "-- Successfully found Anomaly " + entity.toString() );
        }
        catch ( Throwable e ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( msg.toString() + " : " + e );
            
            throw e;
        }

        return( entity );
    }

    /** 
     * Tests updating a Anomaly.
     *
     * @return    Anomaly
     */
    public Anomaly testUpdate() throws Throwable {
        LOGGER.info( "AnomalyTest:testUpdate()" );
        LOGGER.info( "-- Attempting to update a Anomaly." );

        StringBuilder msg = new StringBuilder( "Failed to update a Anomaly : " );        
        Anomaly entity = null;
    
        try {            
        	UpdateAnomalyCommand updateCommand = this.generateUpdateCommand();
        	
        	// apply the current id as to update the fields of the current entity
        	updateCommand.setAnomalyId( theId );
            
            assertNotNull( updateCommand, msg.toString() );

            LOGGER.info( "-- Now updating the created Anomaly." );
            
            AnomalyBusinessDelegate proxy = AnomalyBusinessDelegate.getAnomalyInstance();            
            entity = proxy.updateAnomaly( updateCommand );   
            
            assertNotNull( entity, msg.toString()  );

            LOGGER.info( "-- Successfully saved Anomaly - " + entity.toString() );
        }
        catch ( Throwable e ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );
            
            throw e;
        }

        return( entity );
    }

    /** 
     * Tests deleting a Anomaly.
     */
    public void testDelete() throws Throwable {
        LOGGER.info( "AnomalyTest:testDelete()" );
        LOGGER.info( "-- Deleting a previously created Anomaly." );
        
        try {
        	DeleteAnomalyCommand deleteCommand = new DeleteAnomalyCommand( theId );
        	
            AnomalyBusinessDelegate.getAnomalyInstance().delete( deleteCommand );
            
            LOGGER.info( "-- Successfully deleted Anomaly with primary key " + theId );            
        }
        catch ( Throwable e ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- Failed to delete Anomaly with primary key " + theId );
            
            throw e;
        }
    }

    /** 
     * Tests getting all Anomalys.
     *
     * @return    Collection
     */
    public List<Anomaly> testGetAll() throws Throwable {    
        LOGGER.info( "AnomalyTest:testGetAll() - Retrieving Collection of Anomalys:" );

        StringBuilder msg = new StringBuilder( "-- Failed to get all Anomaly : " );        
        List<Anomaly> collection  = null;

        try {
            // call the static get method on the AnomalyBusinessDelegate
            collection = AnomalyBusinessDelegate.getAnomalyInstance().getAllAnomaly();

            if ( collection == null || collection.size() == 0 ) {
                LOGGER.warning( unexpectedErrorMsg );
                LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
            }
            else {
	            // Now print out the values
	            Anomaly currEntity  = null;            
	            Iterator<Anomaly> iter = collection.iterator();
					
	            while( iter.hasNext() ) {
	                // Retrieve the entity   
	                currEntity = iter.next();
	                
	                assertNotNull( currEntity,"-- null value object in Collection." );
	                assertNotNull( currEntity.getAnomalyId(), "-- value object in Collection has a null primary key" );        
	
	                LOGGER.info( " - " + currEntity.toString() );
	            }
            }
        }
        catch ( Throwable e ){
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( msg.toString() );
            
            throw e;
        }

        return( collection );
    }
    
